<div style="padding:12px 14px 8px;">
<script>
(function(){
  var _cs = document.currentScript;
  var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
  function el(tag, attrs, txt){
    var e = document.createElementNS("http://www.w3.org/2000/svg", tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (txt !== undefined) e.textContent = txt;
    return e;
  }
  function tx(attrs, txt){
    attrs["font-family"] = FONT;
    return el("text", attrs, txt);
  }
  function r2(v){ return Math.round(v * 100) / 100; }
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  var margin = {left:62, right:24, top:18, bottom:46};
  var PW = 680 - margin.left - margin.right;
  var PH = 300 - margin.top - margin.bottom;
  var cats = ["oct. 25","nov.","déc.","janv. 26","févr.","mars","avr.","mai","juin","juill.","août","sept."];
  var headline = [2.2,2.2,2.4,2.3,1.8,2.4,2.8,3.2,2.8,3.0,3.0,3.1];
  var exgas = [2.6,2.6,3.0,3.0,2.4,2.2,2.0,2.2,2.2,2.2,2.4,2.2];
  var n = headline.length;
  var both = headline.concat(exgas);
  var lo = Math.floor(r2(Math.min.apply(null, both) - 0.3) * 2) / 2;
  var hi = Math.ceil(r2(Math.max.apply(null, both) + 0.3) * 2) / 2;
  var xp = function(i){ return margin.left + (i / (n - 1)) * PW; };
  var yp = function(v){ return margin.top + PH * (1 - (v - lo) / (hi - lo)); };
  var plotRight = margin.left + PW;
  var plotBottom = margin.top + PH;
  var step = PW / (n - 1);

  // 1. event band: gasoline up 20% or more year over year, April to September
  var bandX = xp(6) - step / 2;
  svg.appendChild(el("rect", {x: bandX, y: margin.top, width: plotRight - bandX, height: PH, fill: "#c0392b", "fill-opacity": 0.05}));

  // 2. gridlines
  for (var v = lo; v <= hi + 0.001; v += 0.5) {
    svg.appendChild(el("line", {x1: margin.left, x2: plotRight, y1: yp(v), y2: yp(v), stroke: "#ececec", "stroke-width": 0.5}));
  }

  // 3. reference line: 2% inflation target
  var refValue = 2.0;
  var refY = yp(refValue);
  svg.appendChild(el("line", {x1: margin.left, x2: plotRight, y1: refY, y2: refY, stroke: "#2e7d32", "stroke-width": 1, "stroke-dasharray": "3,3"}));

  // 4. series paths
  function pathOf(arr){
    var d = "";
    for (var i = 0; i < arr.length; i++) d += (i === 0 ? "M" : "L") + xp(i).toFixed(1) + " " + yp(arr[i]).toFixed(1) + " ";
    return d;
  }
  svg.appendChild(el("path", {d: pathOf(exgas), fill: "none", stroke: "#9ca3af", "stroke-width": 2, "stroke-linejoin": "round"}));
  svg.appendChild(el("path", {d: pathOf(headline), fill: "none", stroke: "#4a5568", "stroke-width": 2.2, "stroke-linejoin": "round"}));

  // 5. axis lines, then endpoint dots
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: margin.top, y2: plotBottom, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: margin.left, x2: plotRight, y1: plotBottom, y2: plotBottom, stroke: "#d8d8d8", "stroke-width": 1}));
  var lastX = xp(n - 1);
  var lastYh = yp(headline[n - 1]);
  var lastYe = yp(exgas[n - 1]);
  svg.appendChild(el("circle", {cx: lastX, cy: lastYe, r: 4, fill: "#9ca3af"}));
  svg.appendChild(el("circle", {cx: lastX, cy: lastYh, r: 4, fill: "#4a5568"}));

  // 6. gold pill on the headline endpoint, left of the dot
  var pillText = headline[n - 1].toFixed(1).replace(".", ",") + "\u00a0%";
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var pillX = lastX - pillW - 6;
  if (pillX < margin.left) pillX = margin.left;
  var pillY = lastYh - pillH / 2;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx({x: pillX + pillW / 2, y: pillY + pillH / 2 + 3, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111"}, pillText));

  // 7. labels and annotations
  svg.appendChild(tx({x: bandX + (plotRight - bandX) / 2, y: margin.top + 10, "text-anchor": "middle", "font-size": 7, "font-weight": 700, fill: "#c0392b"}, "ESSENCE +20\u00a0% OU PLUS"));
  var currentVal = headline[n - 1];
  if (Math.abs(refValue - currentVal) / currentVal >= 0.03) {
    svg.appendChild(tx({x: margin.left + 10, y: refY + 12, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: "#2e7d32"}, "CIBLE 2\u00a0%"));
  }
  for (var t = lo; t <= hi + 0.001; t += 0.5) {
    svg.appendChild(tx({x: margin.left - 6, y: yp(t) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa"}, t.toFixed(1).replace(".", ",") + "\u00a0%"));
  }
  for (var c = 0; c < n; c++) {
    svg.appendChild(tx({x: xp(c), y: plotBottom + 14, "text-anchor": "middle", "font-size": 8, fill: "#999999"}, cats[c]));
  }
  svg.appendChild(tx({x: lastX - 6, y: lastYe + 16, "text-anchor": "end", "font-size": 8, "font-weight": 700, fill: "#6b7280"}, exgas[n - 1].toFixed(1).replace(".", ",") + "\u00a0%"));

  var legendX = margin.left + 10;
  var legendY = plotBottom - 12;
  var legend = [{name: "IPC global", color: "#4a5568", w: 78}, {name: "IPC excluant l’essence", color: "#9ca3af", w: 110}];
  var offset = 0;
  legend.forEach(function(it){
    svg.appendChild(el("line", {x1: legendX + offset, x2: legendX + offset + 16, y1: legendY, y2: legendY, stroke: it.color, "stroke-width": 2.2}));
    svg.appendChild(tx({x: legendX + offset + 22, y: legendY + 3, "text-anchor": "start", "font-size": 8, fill: "#444444"}, it.name));
    offset += it.w + 30;
  });

  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Statistique Canada, publications mensuelles de l’indice des prix à la consommation, d’octobre 2025 au 19 octobre 2026 (tableau 18-10-0004-01). &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">L’IPC global a dépassé l’IPC excluant l’essence en mars 2026, tandis que l’essence a progressé de 20,5&nbsp;% à 33,2&nbsp;% sur douze mois entre avril et septembre. Les lectures de décembre 2025 à février 2026 reflètent le congé temporaire de TPS/TVH dans la base de l’année précédente.</p>
<h2>Pourquoi l’inquiétude est rationnelle et la généralisation ne l’est pas</h2>
<p>Rien de tout cela ne rend l’inquiétude des ménages irrationnelle. L’essence est un coût réel, et une hausse de 27,8&nbsp;% représente une perte réelle de pouvoir d’achat. Statistique Canada a indiqué que le mazout et les autres combustibles ont augmenté de 57,8&nbsp;% sur douze mois en septembre, l’effet étant plus marqué dans le Canada atlantique, où ce combustible est plus répandu.</p>
<p>Le biais tient à la généralisation&nbsp;: traiter le prix le plus visible comme un indicateur de tous les prix. La recherche donne à penser que cette généralisation est courante, mesurable et lente à se résorber. Scotiabank Economics a écrit le 19 octobre que les propos du gouverneur Tiff Macklem avaient fait fortement monter la probabilité, intégrée aux prix du marché, d’une hausse en octobre. La décision de la Banque du Canada arrive avec un Rapport sur la politique monétaire et un taux directeur de 2,25&nbsp;%, que la Banque a maintenu le 2 septembre.</p>
<p>Si les attentes se forment à la pompe plutôt que dans le panier, le prochain mouvement du pétrole façonnera le comportement des ménages autant que la prochaine publication de l’IPC, que Statistique Canada prévoit pour le 16 novembre.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients qui font le plein chaque semaine vivent les 27,8&nbsp;% comme un fait personnel et lisent l’inflation globale de 3,1&nbsp;% comme une confirmation. Les clients dont l’hypothèque vient à renouvellement au cours des douze prochains mois ont une seconde inquiétude&nbsp;: que la décision de la Banque du Canada du 28 octobre fasse monter le coût d’emprunt. Les retraités à revenu fixe ressentent à la fois la pompe et l’épicerie et sont peu susceptibles de les distinguer. Au fond, l’émotion tient moins de la panique que du sentiment que les coûts ont échappé à tout contrôle.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Je veux vous donner le chiffre derrière le chiffre. L’inflation est de 3,1&nbsp;% au global, mais le même panier sans l’essence est en hausse de 2,2&nbsp;%, ce qui se rapproche de la cible de la Banque du Canada. L’essence a augmenté de 27,8&nbsp;% sur l’année, et c’est ce qui sépare les deux chiffres. Cela ne rend pas le prix à la pompe moins réel pour vous, et je ne le laisse pas entendre. Cela signifie que les prix, dans l’ensemble, se comportent mieux que la station-service ne le laisse croire. La Banque du Canada annonce sa décision mercredi, et quelle qu’elle soit, votre plan a été conçu en tenant compte d’une gamme de scénarios d’inflation, y compris celui-ci. J’aimerais confirmer l’hypothèse d’inflation de votre plan et vérifier si vos besoins de liquidités des douze prochains mois ont changé. Pouvons-nous réserver vingt minutes cette semaine&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les retraités qui touchent un revenu nominal fixe, les clients dont l’hypothèque vient à renouvellement dans les douze mois et les ménages du Canada atlantique qui se chauffent au mazout, lequel a augmenté de 57,8&nbsp;% sur douze mois en septembre.</p>
<p><strong>Incidence variable&nbsp;:</strong> les clients dont le portefeuille est équilibré, qui font face à des coûts de ménage plus élevés tout en détenant des obligations exposées à un possible mouvement des taux, et les clients qui font de longs trajets mais détiennent des actions d’énergie canadiennes.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> les clients exposés à l’énergie canadienne, où la hausse du brut soutient les bénéfices, et les épargnants détenant des titres à revenu fixe à court terme si les taux montent.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Extraire la liste des clients dont l’hypothèque vient à renouvellement dans les douze prochains mois.</div>
<div class="checklist-item">Examiner l’hypothèse d’inflation de chaque plan en fonction de l’inflation globale de 3,1&nbsp;% et de la lecture de 2,2&nbsp;% sans l’essence.</div>
<div class="checklist-item">Repérer les clients retraités dont les retraits sont indexés sur l’inflation et confirmer que la réserve de liquidités couvre douze mois.</div>
<div class="checklist-item">Signaler les clients du Canada atlantique qui comptent sur le mazout pour se chauffer.</div>
<div class="checklist-item">Préparer une courte note à envoyer après l’annonce de 9&nbsp;h&nbsp;45 HE le 28 octobre.</div>
<div class="checklist-item">Consigner chaque conversation avec un client et tout changement dans ses besoins de liquidités.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Inflation, essence et ce que cette semaine signifie pour votre plan<br><br>
Bonjour [Nom du client],<br><br>
Merci d’avoir discuté avec moi aujourd’hui. Pour récapituler l’essentiel&nbsp;: l’inflation globale s’est établie à 3,1&nbsp;% en septembre, mais elle était de 2,2&nbsp;% sans l’essence. L’essence a augmenté de 27,8&nbsp;% sur l’année, ce qui explique l’essentiel de l’écart.<br><br>
La hausse des prix à la pompe est bien réelle, et votre préoccupation est raisonnable. Votre plan, cependant, a été conçu en tenant compte d’une gamme de scénarios d’inflation. La Banque du Canada annonce sa prochaine décision sur les taux le 28 octobre, et je vous reviendrai ensuite pour vous dire ce que cela signifie pour vous.<br><br>
D’ici là, je vais examiner l’hypothèse d’inflation de votre plan et confirmer vos besoins de liquidités pour les douze prochains mois.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs autonomes&nbsp;:</strong> une inflation globale de 3,1&nbsp;% avec une essence en hausse de 27,8&nbsp;% invite à des décisions fondées sur le prix le plus visible, comme se réfugier dans les liquidités ou courir après les actions du secteur de l’énergie, sans personne pour éprouver le raisonnement.</p>
<p><strong>Propriétaires approchant d’un renouvellement&nbsp;:</strong> la décision du 28 octobre met le risque de taux devant des personnes qui n’ont peut-être pas de plan pour y faire face.</p>
<p><strong>Retraités détenant d’importants soldes en liquidités&nbsp;:</strong> la hausse des attentes d’inflation soulève la question de savoir si les liquidités suivent le rythme.</p>
<p><strong>Propriétaires de petites entreprises aux coûts liés au carburant&nbsp;:</strong> ils ressentent directement le prix de l’essence et songent peut-être à revoir leur épargne personnelle et celle de leur société.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">L’inflation s’est établie à 3,1&nbsp;% le 19 octobre, mais elle est de 2,2&nbsp;% sans l’essence, et j’ai constaté que cette différence change la façon dont les gens envisagent leurs plans. Avez-vous deux minutes&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Ce moment ouvre une fenêtre de prospection parce que l’écart entre ce que l’inflation donne à ressentir et ce qu’elle mesure est exceptionnellement large. L’essence est le prix le plus visible du panier, et la recherche donne à penser que les ménages en tirent des généralisations. L’investisseur qui gère lui-même son argent n’a aucun cadre pour distinguer le prix à la pompe de l’inflation sous-jacente, ni personne à qui demander si sa réaction est proportionnée.</p>
<p>L’asymétrie relevée par la recherche compte ici&nbsp;: les attentes montent rapidement lorsqu’on s’attend à une hausse du prix de l’essence et ne reviennent pas nécessairement en arrière lorsque ces attentes s’atténuent. L’inquiétude risque de persister au-delà de la prochaine publication de l’IPC. Le conseiller offre une façon structurée de distinguer ce qui est mesuré de ce qui est ressenti, et un plan qui tient quoi qu’il arrive.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<p>1. Comment la dernière année de hausses de prix a-t-elle changé votre façon de penser à vos finances&nbsp;?</p>
<p>2. Quand vous entendez que l’inflation est de 3,1&nbsp;%, à quoi l’attribuez-vous&nbsp;?</p>
<p>3. Votre plan actuel comprend-il une hypothèse d’inflation explicite, et quand l’avez-vous vérifiée pour la dernière fois&nbsp;?</p>
<p>4. Le prix de l’essence ou de l’énergie vous a-t-il amené à modifier vos placements ou la part que vous gardez en liquidités&nbsp;?</p>
<p>5. Si les taux bougeaient mercredi, qui appelleriez-vous pour en discuter&nbsp;?</p>
</div>
