    attrs["font-family"] = FONT;
    return el("text", attrs, txt);
  }
  var svg = document.createElementNS("http://www.w3.org/2000/svg","svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  var margin = {left:62, right:24, top:18, bottom:46};
  var PW = 680 - margin.left - margin.right;
  var PH = 300 - margin.top - margin.bottom;

  // U.S. goods imports from Canada, US$ billions, monthly, January 2025 to August 2026
  var imp = [38.95,34.79,34.97,29.10,29.98,29.65,32.20,29.14,31.75,31.24,28.51,31.66,
             28.33,29.17,34.09,35.03,36.34,37.22,33.49,35.98];
  var MONTHS = ["janv.","févr.","mars","avr.","mai","juin","juill.","août","sept.","oct.","nov.","déc."];
  var n = imp.length;
  var base = imp.slice(0, 12);
  var avg25 = base.reduce(function(a, b){ return a + b; }, 0) / base.length;
  var lo = Math.floor((Math.min.apply(null, imp) - 2) / 5) * 5;
  var hi = Math.ceil((Math.max.apply(null, imp) + 2) / 5) * 5;
  var xp = function(i){ return margin.left + (i / (n - 1)) * PW; };
  var yp = function(v){ return margin.top + PH * (1 - (v - lo) / (hi - lo)); };
  var plotRight = margin.left + PW;
  var plotBottom = margin.top + PH;

  // 1. event band: the Iran war period, from March 2026
  var warI = 14;
  var bandX = xp(warI - 0.5);
  svg.appendChild(el("rect", {x: bandX, y: margin.top, width: plotRight - bandX, height: PH, fill: "#c0392b", "fill-opacity": 0.05}));

  // 2. gridlines
  for (var v = lo; v <= hi + 0.001; v += 5) {
    svg.appendChild(el("line", {x1: margin.left, x2: plotRight, y1: yp(v), y2: yp(v), stroke: "#ececec", "stroke-width": 0.5}));
  }

  // 3. reference line: the 2025 monthly average, and the August 22 tariff marker
  var refY = yp(avg25);
  svg.appendChild(el("line", {x1: margin.left, x2: plotRight, y1: refY, y2: refY, stroke: "#2e7d32", "stroke-width": 1, "stroke-dasharray": "3,3"}));
  var tariffI = n - 1 - 9 / 31;
  var markX = xp(tariffI);
  svg.appendChild(el("line", {x1: markX, x2: markX, y1: margin.top, y2: plotBottom, stroke: "#888888", "stroke-width": 1, "stroke-dasharray": "3,3"}));

  // 4. series path
  var d = "";
  for (var i = 0; i < n; i++) d += (i === 0 ? "M" : "L") + xp(i).toFixed(1) + " " + yp(imp[i]).toFixed(1) + " ";
  svg.appendChild(el("path", {d: d, fill: "none", stroke: "#4a5568", "stroke-width": 2.2, "stroke-linejoin": "round"}));

  // 5. axis lines, then endpoint dot
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: margin.top, y2: plotBottom, stroke: "#d8d8d8", "stroke-width": 1}));
  svg.appendChild(el("line", {x1: margin.left, x2: plotRight, y1: plotBottom, y2: plotBottom, stroke: "#d8d8d8", "stroke-width": 1}));
  var lastX = xp(n - 1);
  var lastV = imp[n - 1];
  var lastY = yp(lastV);
  svg.appendChild(el("circle", {cx: lastX, cy: lastY, r: 4, fill: "#4a5568"}));

  // 6. gold pill on the endpoint, left of the dot
  var pillText = lastV.toFixed(1).replace(".", ",") + " Md$";
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var pillX = lastX - pillW - 6;
  if (pillX < margin.left) pillX = margin.left;
  var pillY = lastY - pillH / 2;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(tx({x: pillX + pillW / 2, y: pillY + pillH / 2 + 3, "text-anchor": "middle", "font-size": 9, "font-weight": 700, fill: "#111111"}, pillText));

  // 7. labels and annotations
  svg.appendChild(tx({x: bandX + (plotRight - bandX) / 2, y: plotBottom - 8, "text-anchor": "middle", "font-size": 7, "font-weight": 700, fill: "#c0392b"}, "GUERRE EN IRAN"));
  svg.appendChild(tx({x: markX - 5, y: margin.top + 10, "text-anchor": "end", "font-size": 7, "font-weight": 700, fill: "#666666"}, "DROITS 50 % DÈS 22 AOÛT"));
  svg.appendChild(tx({x: xp(8) + 4, y: refY - 5, "text-anchor": "start", "font-size": 7, "font-weight": 700, fill: "#2e7d32"}, "MOY. 2025 " + avg25.toFixed(1).replace(".", ",") + " Md$"));
  for (var t = lo; t <= hi + 0.001; t += 5) {
    svg.appendChild(tx({x: margin.left - 6, y: yp(t) + 3, "text-anchor": "end", "font-size": 8.5, fill: "#aaaaaa"}, t + " Md$"));
  }
  for (var c = 1; c < n; c += 3) {
    svg.appendChild(tx({x: xp(c), y: plotBottom + 14, "text-anchor": "middle", "font-size": 8, fill: "#999999"}, MONTHS[c % 12] + " " + (25 + Math.floor(c / 12))));
  }

  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Bureau du recensement des États-Unis, «&nbsp;Trade in Goods with Canada&nbsp;» (dollars US nominaux, non désaisonnalisés)&nbsp;; Statistique Canada, publication commerciale d’août 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Les importations américaines en provenance du Canada ont atteint en moyenne 31,8&nbsp;milliards de dollars US par mois en 2025 et ont dépassé cette moyenne chaque mois depuis mars 2026. Les droits de 50&nbsp;% sont entrés en vigueur le 22 août, de sorte qu’août n’en capte que dix jours, et Affaires mondiales Canada note que les exportateurs ont peut-être devancé des expéditions avant cette date. Les chiffres sont nominaux et non désaisonnalisés.</p>
<p>Le pétrole explique en partie l’écart entre cette vigueur et les dégâts tarifaires. Le Brent a clôturé à 72,48&nbsp;$&nbsp;US le 27 février, la veille du début des frappes contre l’Iran, et se situait à environ 114,50&nbsp;$&nbsp;US le 25 octobre, en baisse d’environ 2&nbsp;% par rapport à un sommet de près de six mois, a rapporté Al Jazeera.</p>
<p>Il s’agit d’un effet de masquage, et non d’un verdict sur les droits de douane. La hausse des prix gonfle la valeur de l’énergie expédiée vers le sud, et cette valeur figure dans les mêmes totaux mensuels que les secteurs frappés par les droits tirent vers le bas.</p>
<h2>Ormuz est la seconde horloge</h2>
<p>Le Commandement central des États-Unis (CENTCOM) a indiqué le 25 octobre que les forces américaines ont aidé les États du Golfe à exporter plus de 1,5&nbsp;milliard de barils depuis juin et que plus de 95&nbsp;% des navires qui transitent par le détroit l’ont fait en sécurité. Kpler estime que 16,5 millions de barils par jour ont quitté la région en septembre, ce qui correspond à la moyenne d’avant-guerre excluant l’Iran.</p>
<p>Les flux reposent sur des contournements. Kpler estime qu’environ 40&nbsp;% des exportations pétrolières du Moyen-Orient contournent maintenant le détroit, et qu’une bonne partie du brut qui le traverse est transférée entre pétroliers au large. L’UKMTO a rapporté au moins une attaque par jour dans le détroit d’Ormuz ou le golfe d’Aden du 2 au 6 octobre.</p>
<p>Amin Nasser, chef de la direction de Saudi Aramco, a dit qu’environ trois milliards de barils d’approvisionnement ont été perdus depuis la fin de février et que la reconstitution des stocks pourrait prendre jusqu’à deux ans. «&nbsp;Le système est déjà sous tension&nbsp;», a-t-il dit. Tamas Varga, de PVM Oil Associates, a dit que les flux sont soutenables tant que le pipeline Est-Ouest et les routes de transbordement entre navires demeurent sûrs, et que seul un accord de paix durable et crédible rétablirait les conditions d’avant le conflit.</p>
<h2>Scénario de base, risque de queue et points à surveiller</h2>
<p>Le scénario de base est qu’aucune entente n’arrive avant le 3 novembre, que les droits de 50&nbsp;% persistent et que le pétrole au-dessus de 100&nbsp;$&nbsp;US maintient élevée la valeur des exportations d’énergie. La décision de la Banque du Canada du 28 octobre s’inscrit dans ce cadre, puisque Desjardins a cité les droits de rétorsion comme un risque pour l’inflation.</p>
<p>Deux risques de queue vont en sens opposés. Une entente éclair, dont le ministre du Commerce Dominic LeBlanc a dit à un comité consultatif qu’elle relève de la zone où «&nbsp;tout est possible&nbsp;», soulagerait les secteurs visés. Un règlement durable dans le Golfe ferait baisser le prix du pétrole et supprimerait la compensation qui flatte les totaux commerciaux, exposant le poids des droits de douane. Ni l’un ni l’autre n’est le résultat attendu, et chacun ferait réévaluer les exportateurs canadiens et le huard dans des directions différentes.</p>
<p>Les dates à surveiller sont la fin d’octobre, moment où la liste tarifaire révisée prend effet, et le 3 novembre, quand le vote américain remet à zéro l’horloge de négociation. M. Carney s’est entretenu avec le président Donald Trump le 21 octobre au sujet du commerce et de la guerre en Iran, et son bureau n’a publié aucun compte rendu officiel.</p>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les propriétaires d’entreprise qui ont des clients américains se sentent exposés et ne savent pas s’il faut attendre une entente qui ne viendra probablement pas. Les investisseurs détenant de l’énergie ressentent une confusion discrète&nbsp;: les manchettes commerciales sont mauvaises, mais les chiffres d’exportation paraissent solides. Les clients qui suivent l’actualité vivent deux crises à la fois, les droits de douane à la frontière et une guerre dans le Golfe, et plusieurs ne savent pas laquelle compte le plus pour leur épargne.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Voici où en sont les choses. Une entente commerciale avec les États-Unis n’est pas attendue avant les élections américaines de mi-mandat du 3 novembre, de sorte que les droits de 50&nbsp;% sur une longue liste de produits canadiens risquent de rester en place pour l’instant. En même temps, les données d’exportation paraissent solides, surtout parce que les prix du pétrole sont élevés depuis le début de la guerre en Iran, et cette vigueur peut s’inverser si le pétrole recule. C’est pourquoi je ne veux pas décider à partir d’une seule manchette. Votre plan a été conçu pour des périodes de friction commerciale et de fluctuations du pétrole, et j’aimerais vérifier deux choses avec vous&nbsp;: la part de votre revenu ou de votre portefeuille qui dépend du commerce avec les États-Unis ou de l’énergie canadienne, et si quelque chose s’est écarté de vos cibles. Pouvons-nous trouver vingt minutes cette semaine&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les propriétaires d’entreprise qui exportent vers les États-Unis ou achètent des intrants américains, surtout dans les secteurs de la liste des 50&nbsp;% comme le contreplaqué, le matériel électrique et les boissons alcoolisées, et les clients dont l’employeur évolue dans ces secteurs.</p>
<p><strong>Incidence variable&nbsp;:</strong> les clients détenant de l’énergie canadienne, qui profitent d’un pétrole près de 100&nbsp;$&nbsp;US mais portent le risque d’un accord de paix ou d’un choc d’approvisionnement, et les investisseurs exposés au dollar canadien, qui peut bouger dans un sens ou dans l’autre selon les nouvelles commerciales ou le pétrole.</p>
<p><strong>Incidence indirecte&nbsp;:</strong> les retraités et les épargnants, qui la ressentent par les prix à la consommation et la trajectoire des taux de la Banque du Canada plutôt que directement par le commerce.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Repérer les clients propriétaires d’entreprise ayant des ventes ou des intrants américains et noter les produits échangés.</div>
<div class="checklist-item">Comparer l’exposition des clients à la liste tarifaire révisée qui prend effet à la fin d’octobre.</div>
<div class="checklist-item">Examiner la concentration en énergie dans les portefeuilles des clients par rapport aux cibles établies.</div>
<div class="checklist-item">Signaler les clients ayant d’importants avoirs ou revenus en dollars américains et vérifier l’exposition au change.</div>
<div class="checklist-item">Réserver un bref suivi pour la semaine du 9 novembre, après les élections de mi-mandat du 3 novembre.</div>
<div class="checklist-item">Consigner chaque conversation et tout changement de tolérance au risque.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Commerce, pétrole et votre plan&nbsp;: ce qui est réglé et ce qui ne l’est pas<br><br>
Bonjour [Nom du client],<br><br>
Merci d’avoir discuté avec moi aujourd’hui. Pour récapituler&nbsp;: une entente commerciale Canada-États-Unis n’est pas attendue avant les élections de mi-mandat du 3 novembre, de sorte que les droits de 50&nbsp;% sur une longue liste de produits canadiens resteront probablement en place pour l’instant. Les exportations canadiennes vers les États-Unis ont été vigoureuses, en grande partie à cause de la hausse des prix du pétrole, et ce soutien peut s’inverser si le pétrole recule.<br><br>
Votre plan a été conçu pour des périodes de friction commerciale et de fluctuations des prix de l’énergie. Je vais examiner votre exposition au commerce avec les États-Unis et à l’énergie canadienne, et je vous reviendrai après les élections de mi-mandat.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Propriétaires d’entreprise qui exportent vers les États-Unis&nbsp;:</strong> ils vivent avec le mur tarifaire et ont le plus à gagner d’une conversation de planification sur la trésorerie de la société, la rémunération du propriétaire et le risque.</p>
<p><strong>Investisseurs autonomes aux avoirs énergétiques concentrés&nbsp;:</strong> un pétrole près de 100&nbsp;$&nbsp;US a fait monter les rendements, et peu ont un plan pour le cas où le Golfe se stabiliserait.</p>
<p><strong>Professionnels des secteurs exposés aux droits de douane&nbsp;:</strong> les employés des entreprises forestières, manufacturières et de boissons alcoolisées s’inquiètent peut-être pour leur emploi et veulent un plan.</p>
<p><strong>Clients ayant des revenus ou des actifs en dollars américains&nbsp;:</strong> les nouvelles commerciales et le pétrole font tous deux bouger le dollar canadien, ce qui change la valeur de ce qu’ils détiennent.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Une entente commerciale avec les États-Unis n’est pas attendue avant les élections de mi-mandat du 3 novembre, et des prix du pétrole élevés masquent une partie des dégâts dans les chiffres d’exportation. J’ai préparé une courte note sur ce que cela signifie pour les propriétaires d’entreprise et les investisseurs. Avez-vous deux minutes&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Le commerce et la géopolitique créent une fenêtre de prospection parce que les signaux se contredisent. Les droits de douane sont de 50&nbsp;% sur une longue liste de produits, et pourtant la valeur des exportations est supérieure de 23,7&nbsp;% à celle d’il y a un an, de sorte qu’une personne qui gère son propre argent n’a aucun moyen fiable de savoir si l’économie est vigoureuse ou si les dégâts sont masqués.</p>
<p>Le conseiller offre une façon de les distinguer&nbsp;: quelles expositions dépendent des droits de douane, lesquelles dépendent du pétrole et lesquelles dépendent des deux. Un plan qui tient si le pétrole recule ou si une entente arrive vaut plus qu’une réaction à une seule manchette, et les semaines suivant le 3 novembre sont un moment naturel pour commencer.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<p>1. Votre entreprise ou votre employeur vend-il aux États-Unis, et quels produits&nbsp;?</p>
<p>2. Comment les droits de douane ont-ils touché jusqu’ici votre revenu, vos coûts ou vos projets&nbsp;?</p>
<p>3. Quelle part de votre portefeuille se trouve dans l’énergie canadienne, et comment avez-vous déterminé ce montant&nbsp;?</p>
<p>4. Si le pétrole chutait fortement, qu’est-ce que cela ferait à votre épargne&nbsp;?</p>
<p>5. À qui parlez-vous lorsque des nouvelles commerciales ou géopolitiques soulèvent une question sur votre plan&nbsp;?</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de prospection</div>
<div class="email-box" id="prospect-email">
<strong>Objet&nbsp;:</strong> Pourquoi de solides chiffres d’exportation ne signifient pas forcément que les droits de douane sont absorbés<br><br>
Bonjour [Nom du prospect],<br><br>
Les exportations canadiennes vers les États-Unis sont en hausse de 23,7&nbsp;% sur un an, même si un mur tarifaire de 50&nbsp;% est entré en vigueur le 22 août. Une bonne partie de cette vigueur reflète la hausse des prix du pétrole depuis le début de la guerre en Iran, qui peut s’inverser. Une entente commerciale n’est pas attendue avant les élections de mi-mandat du 3 novembre.<br><br>
Si cela vous est utile, je me ferai un plaisir de vous présenter en quinze minutes quelles parties d’un plan dépendent du commerce, lesquelles dépendent du pétrole et lesquelles des deux.<br><br>
Cela vous conviendrait-il plus tard cette semaine&nbsp;?<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button>
</div>',
  '[{"value":"50 %","label":"Droits en vigueur le 22 août"},{"value":"23,7 %","label":"Exportations vers É.-U., an/an"},{"value":"114,50 $ US","label":"Brent le 25 octobre"},{"value":"3 nov.","label":"Élections américaines de mi-mandat"}]',
